put,flush=make_put(A)
t,u,v,a_,b_,c_=S.symbols('theta u v alpha beta gamma')
sin,cos,tan,cot,sec,csc,sqrt=S.sin,S.cos,S.tan,S.cot,S.sec,S.csc,S.sqrt
random.seed(11)
def numchk(l,r,syms,n=6):
    for _ in range(n):
        sub={s:random.uniform(0.2,1.2) for s in syms}
        assert abs(S.N(l.subs(sub))-S.N(r.subs(sub)))<1e-9,(l,r,sub)
def prf(ex,q,p,lines,l=None,r=None,syms=()):
    if l is not None:numchk(l,r,syms)
    put(ex,q,p,'Proved.',[work(x) for x in lines],category='proofs',answerUr=PROVED[1],answerPs=PROVED[2])
def val(ex,q,p,ans,lines,**kw):
    put(ex,q,p,ans,[work(x) for x in lines],**kw)
def D(v):return S.N(v,12)
