prf('10.1',8,'',[r'\text{(i) }\tan\left(\tfrac\pi4+\theta\right)=\frac{1+\tan\theta}{1-\tan\theta}=\frac{\cos\theta+\sin\theta}{\cos\theta-\sin\theta}\ \ (\text{multiply by }\cos\theta)',r'\text{(ii) }\tan\left(\tfrac\pi4-\theta\right)=\frac{\tan\frac\pi4-\tan\theta}{1+\tan\frac\pi4\tan\theta}=\frac{1-\tan\theta}{1+\tan\theta}',r'\text{(iii) }\frac{\tan(\alpha+\beta)}{\cot(\alpha-\beta)}=\tan(\alpha+\beta)\tan(\alpha-\beta)=\frac{\tan\alpha+\tan\beta}{1-\tan\alpha\tan\beta}\cdot\frac{\tan\alpha-\tan\beta}{1+\tan\alpha\tan\beta}=\frac{\tan^2\alpha-\tan^2\beta}{1-\tan^2\alpha\tan^2\beta}',r'\text{(iv) }\frac{\cos(\theta+\phi)}{\cos(\theta-\phi)}=\frac{\cos\theta\cos\phi-\sin\theta\sin\phi}{\cos\theta\cos\phi+\sin\theta\sin\phi}=\frac{1-\tan\theta\tan\phi}{1+\tan\theta\tan\phi}\ \ (\text{divide by }\cos\theta\cos\phi)'],tan(S.pi/4+a_)*0+tan(a_+b_)*tan(a_-b_),(tan(a_)**2-tan(b_)**2)/(1-tan(a_)**2*tan(b_)**2),(a_,b_))
