dbl=step(r'Use $\sin2\theta=2\sin\theta\cos\theta$, $\cos2\theta=\cos^2\theta-\sin^2\theta=2\cos^2\theta-1=1-2\sin^2\theta$, $\tan2\theta=\frac{2\tan\theta}{1-\tan^2\theta}$.',r'$\sin2\theta=2\sin\theta\cos\theta$، $\cos2\theta=\cos^2\theta-\sin^2\theta=2\cos^2\theta-1=1-2\sin^2\theta$، $\tan2\theta=\frac{2\tan\theta}{1-\tan^2\theta}$ استعمال کریں۔',r'$\sin2\theta=2\sin\theta\cos\theta$، $\cos2\theta=\cos^2\theta-\sin^2\theta=2\cos^2\theta-1=1-2\sin^2\theta$، $\tan2\theta=\frac{2\tan\theta}{1-\tan^2\theta}$ وکاروئ.')
half=step(r'Use $\sin\frac\theta2=\pm\sqrt{\frac{1-\cos\theta}2}$, $\cos\frac\theta2=\pm\sqrt{\frac{1+\cos\theta}2}$, $\tan\frac\theta2=\frac{1-\cos\theta}{\sin\theta}$, choosing the sign from the quadrant of $\frac\theta2$.',r'$\sin\frac\theta2=\pm\sqrt{\frac{1-\cos\theta}2}$، $\cos\frac\theta2=\pm\sqrt{\frac{1+\cos\theta}2}$، $\tan\frac\theta2=\frac{1-\cos\theta}{\sin\theta}$ استعمال کریں اور علامت $\frac\theta2$ کے ربع سے چنیں۔',r'$\sin\frac\theta2=\pm\sqrt{\frac{1-\cos\theta}2}$، $\cos\frac\theta2=\pm\sqrt{\frac{1+\cos\theta}2}$، $\tan\frac\theta2=\frac{1-\cos\theta}{\sin\theta}$ وکاروئ او نښه د $\frac\theta2$ د ربع نه وټاکئ.')
