prf('Review 10',9,'(i)',[r'\sin^2(\pi+\theta)=\sin^2\theta,\ \tan\left(\tfrac{3\pi}2+\theta\right)=-\cot\theta,\ \cot^2\left(\tfrac{3\pi}2-\theta\right)=\tan^2\theta,\ \cos^2(\pi-\theta)=\cos^2\theta,\ \csc(2\pi-\theta)=-\csc\theta',r'\frac{\sin^2\theta(-\cot\theta)}{\tan^2\theta\cos^2\theta(-\csc\theta)}=\frac{\sin^2\theta\cot\theta}{\sin^2\theta\csc\theta}=\frac{\cot\theta}{\csc\theta}=\cos\theta'])
